package com.bulletin.app;
import org.junit.Test;
import org.json.*;
import java.time.*;
import static org.junit.Assert.*;
public class CompactSaveTest {
 private final long now=Instant.parse("2026-10-31T12:00:00.123Z").toEpochMilli();private final ZoneId zone=ZoneId.of("UTC");
 private Game sample(){Game g=new Game(now,zone);g.coins=12345;g.hue=198.125f;Game.Category c=new Game.Category();c.name="Home";c.hue=42;c.mustDo=true;c.requiredTasks=3;c.progressDay=g.day;g.addCategory(c);
  Game.Quest q=new Game.Quest();q.name="Focus shared";q.firstDay=g.day;q.repeatable=true;q.forever=true;q.emoji="\ud83c\udfaf";q.prerequisites.add("Prepare");g.addQuest(q);g.assignCategory(q,c.id);g.start(q,now);g.pauseQuest(now+1234);g.start(q,now+2345);
  Game.Fine law=new Game.Fine();law.name="Law";law.mode=Game.TIMED;law.timeLimitMillis=60000;law.remainingMillis=60000;law.endsAt=now+60000;g.addLaw(law);
  Game.HistoryEntry e=new Game.HistoryEntry(Game.QUEST_HISTORY,q.id,q.name,now-12345);e.coinsKnown=true;e.coinsDelta=37;g.history.add(e);g.focus.add(new Game.FocusEntry(q.id,q.name,g.day,1234));g.timedMillisToday=1234;
  g.balances.clear();g.balances.add(new Game.BalancePoint(now,12345,"Quest completed: "+q.name));g.balanceRangeStart=now-1111;g.balanceRangeEnd=now;g.questTimelineStart=now-2222;g.questTimelineEnd=now;g.lawTimelineStart=now-3333;
  g.collapsedAnalyticsSections.add("0:0:"+c.id);g.randomQuestIds.add(q.id);g.randomDay=g.day;g.excludedRandomCategories.add(c.id);
  Game.Quest archived=new Game.Quest();archived.id="12345678-1234-1234-1234-123456789abc";archived.name="Archived";archived.firstDay=g.day-1;g.deletedQuests.add(archived);g.questsCreated=2;
  Game.UndoEntry u=new Game.UndoEntry();u.questId=q.id;u.categoryId=c.id;u.at=now-123;u.reward=27;u.bountyBefore=100;u.bountyAfter=120;g.undo.add(u);
  Game.MissedReview r=new Game.MissedReview();r.day=g.day-1;r.coinsLost=100;r.daysLost=1;r.ids.add(q.id);r.names.add(q.name);g.missedReviews.add(r);return g;}
 @Test public void historicalRenamesAndExplicitEmptyNamesRemainExact()throws Exception{Game g=sample();g.history.get(0).name="Earlier name";g.focus.get(0).name="";Game loaded=GameCodec.decode(GameCodec.encode(g).toString(),now,zone);assertEquals("Earlier name",loaded.history.get(0).name);assertEquals("",loaded.focus.get(0).name);assertEquals(g.session.questName,loaded.session.questName);}
 @Test public void frozenSchema18FixtureRemainsReadableAcrossFutureChanges()throws Exception{String text;try(java.io.InputStream input=getClass().getResourceAsStream("/schema18.json");java.util.Scanner scanner=new java.util.Scanner(input,"UTF-8")){text=scanner.useDelimiter("\\A").next();}Game g=GameCodec.decode(text,1793448000123L,zone);assertEquals(4242,g.coins);assertEquals(12,g.days);assertEquals(42,g.nextEntityId);assertEquals("12345678-1234-1234-1234-123456789abc",g.quests.get(0).id);assertEquals("Golden quest",g.session.questName);assertEquals(1793448000123L+900000,g.session.endsAt);assertEquals(3,g.history.get(0).count);assertEquals(37,g.history.get(0).coinsDelta);assertEquals("Earlier name",g.history.get(0).name);assertEquals(12345,g.timedMillisToday);assertEquals(-700,g.balances.get(0).minimum);assertEquals(900,g.balances.get(0).maximum);assertEquals(1793448000123L-100000000,g.questTimelineStart);}
 @Test public void compactRoundTripPreservesEveryGameplayFieldAndReference()throws Exception{Game g=sample();JSONObject wire=GameCodec.encode(g);assertEquals(18,wire.getInt("version"));assertFalse(wire.has("quests"));Game loaded=GameCodec.decode(wire.toString(),now,zone);assertEquals(GameCodec.encodeLegacy(g).toString(),GameCodec.encodeLegacy(loaded).toString());}
 @Test public void poolsTextOnceAndMakesTheUncompressedJsonSmaller()throws Exception{Game g=sample();for(int i=0;i<100;i++)g.history.add(new Game.HistoryEntry(Game.QUEST_HISTORY,g.quests.get(0).id,"Focus shared",now-i*1000));String full=GameCodec.encodeLegacy(g).toString(),compact=GameCodec.encode(g).toString();assertTrue(compact.length()<full.length()/2);assertEquals(1,compact.split("Focus shared",-1).length-1);}
 @Test public void oldJsonAndB1B3SavesStillLoad()throws Exception{Game g=sample();JSONObject old=GameCodec.encodeLegacy(g).put("version",17);for(String saved:new String[]{old.toString(),SaveCompression.packLegacy(old.toString()),SaveCompression.pack(old.toString()),SaveCompression.pack(GameCodec.encode(g).toString())}){Game loaded=SaveImports.decode(saved,now,zone);assertEquals(g.coins,loaded.coins);assertEquals(g.quests.get(0).id,loaded.quests.get(0).id);assertEquals(g.session.endsAt,loaded.session.endsAt);}}
 @Test public void millisecondsSentinelsAndMaximumTimerDeadlineRemainExact()throws Exception{Game g=sample();g.session.endsAt=Long.MAX_VALUE;g.lastSeenAt=now+999;Game loaded=GameCodec.decode(GameCodec.encode(g).toString(),now,zone);assertEquals(Long.MAX_VALUE,loaded.session.endsAt);assertEquals(now+999,loaded.lastSeenAt);assertEquals(Long.MIN_VALUE,loaded.quests.get(0).completedDay);assertEquals(g.undo.get(0).at,loaded.undo.get(0).at);}
 @Test public void derivedDailyTimeDoesNotOverwriteAnExplicitLegacyTotal()throws Exception{Game g=sample();assertEquals(1234,GameCodec.decode(GameCodec.encode(g).toString(),now,zone).timedMillisToday);g.timedMillisToday=0;assertEquals(0,GameCodec.decode(GameCodec.encode(g).toString(),now,zone).timedMillisToday);}
 @Test public void newIdsAreShortStableAndNeverReusedAfterDeletion()throws Exception{Game g=sample();String id=g.quests.get(0).id;assertTrue(id.length()<8);Game loaded=GameCodec.decode(GameCodec.encode(g).toString(),now,zone);assertEquals(id,loaded.quests.get(0).id);loaded.deleteQuest(loaded.quests.get(0));Game.Quest next=new Game.Quest();next.firstDay=loaded.day;loaded.addQuest(next);assertNotEquals(id,next.id);assertTrue(next.id.length()<8);assertEquals("12345678-1234-1234-1234-123456789abc",loaded.deletedQuests.get(0).id);}
 @Test public void unknownAdapterFieldsArePreservedAndCorruptOrFutureCompactSavesRejected()throws Exception{JSONObject full=GameCodec.encodeLegacy(sample()).put("extension",new JSONObject().put("value",17));assertEquals(17,CompactSave.expand(CompactSave.pack(full)).getJSONObject("extension").getInt("value"));JSONObject compact=GameCodec.encode(sample());compact.put("s",new JSONArray());try{GameCodec.decode(compact.toString(),now,zone);fail("Bad string references accepted");}catch(JSONException expected){}compact=GameCodec.encode(sample()).put("v",19);try{GameCodec.decode(compact.toString(),now,zone);fail("Future save accepted");}catch(GameCodec.FutureVersion expected){}}
}